#!/usr/bin/env bash
set -e
echo "=== Updating RampPulse on VPS ==="
cd /opt/ramppulse

python3 - << "PYEOF"
import zlib, base64, pathlib
p_backend_auth_py = ""
pathlib.Path("backend/auth.py").write_bytes(zlib.decompress(base64.b64decode(p_backend_auth_py)))
print("[+] backend/auth.py written successfully")
p_backend_chat_py = ""
pathlib.Path("backend/chat.py").write_bytes(zlib.decompress(base64.b64decode(p_backend_chat_py)))
print("[+] backend/chat.py written successfully")
p_backend_main_py = ""
pathlib.Path("backend/main.py").write_bytes(zlib.decompress(base64.b64decode(p_backend_main_py)))
print("[+] backend/main.py written successfully")
p_frontend_chat_js = ""
pathlib.Path("frontend/chat.js").write_bytes(zlib.decompress(base64.b64decode(p_frontend_chat_js)))
print("[+] frontend/chat.js written successfully")
p_frontend_chat_css = ""
pathlib.Path("frontend/chat.css").write_bytes(zlib.decompress(base64.b64decode(p_frontend_chat_css)))
print("[+] frontend/chat.css written successfully")
p_frontend_index_html = ""
pathlib.Path("frontend/index.html").write_bytes(zlib.decompress(base64.b64decode(p_frontend_index_html)))
print("[+] frontend/index.html written successfully")
p_frontend_engineer_html = ""
pathlib.Path("frontend/engineer.html").write_bytes(zlib.decompress(base64.b64decode(p_frontend_engineer_html)))
print("[+] frontend/engineer.html written successfully")
p_frontend_app_js = ""
pathlib.Path("frontend/app.js").write_bytes(zlib.decompress(base64.b64decode(p_frontend_app_js)))
print("[+] frontend/app.js written successfully")
PYEOF

nginx -t && systemctl reload nginx || true
systemctl restart ramppulse
sleep 1

echo "=== Verification ==="
curl -s http://127.0.0.1:8000/healthz
echo ""
curl -s "http://127.0.0.1:8000/api/users/search?q=orlov" || true
echo ""
echo "=== VPS Update Complete! ==="